mapper.select:
SELECT * FROM t_dict
WHERE 1=1

    AND type_code = #{typeCode}


    AND status = #{status}

ORDER BY type_code, sort ASC

mapper.insert:
INSERT INTO t_dict (
    type_code, label, value, sort, status, remark,
    created_at, created_by, updated_at, updated_by
) VALUES (
    #{typeCode}, #{label}, #{value}, #{sort}, #{status}, #{remark},
    NOW(), #{createdBy}, NOW(), #{updatedBy}
)
